// Define a message
public class MyMessage {
    public int data;
    public MyMessage() {}
    public MyMessage(int data) { this.data = data; }
}

// Create the network channel
private static final String PROTOCOL_VERSION = "1";
public static final SimpleChannel NETWORK = NetworkRegistry.newSimpleChannel(
    new ResourceLocation(MODID, "main"),
    () -> PROTOCOL_VERSION,
    PROTOCOL_VERSION::equals,
    PROTOCOL_VERSION::equals
);

// Register message handlers
private static final AtomicInteger ID = new AtomicInteger(0);
public static void register() {
    NETWORK.registerMessage(ID.getAndIncrement(), MyMessage.class, 
        (msg, buf) -> { buf.writeInt(msg.data); },
        (buf) -> new MyMessage(buf.readInt()),
        (msg, ctx) -> {
            msg.handle(ctx.getSender());
        }
    );
}

// Sending messages
// Server to client: NETWORK.send(PacketDistributor.PLAYER.with(() -> player), new MyMessage(42));
// Client to server: NETWORK.sendToServer(new MyMessage(42));
